package main

import (
	"fmt"
	"path/filepath"
)

func main() {
	base := "workspace"
	target := filepath.Join(base, "reports", "summary.csv")
	relative, err := filepath.Rel(base, target)
	if err != nil {
		panic(err)
	}
	fmt.Println("clean:", filepath.Clean(target))
	fmt.Println("base:", filepath.Base(target))
	fmt.Println("dir:", filepath.Dir(target))
	fmt.Println("ext:", filepath.Ext(target))
	fmt.Println("rel:", relative)
}
