package main

import (
	"fmt"
	"io"
	"os"
	"path/filepath"
)

func main() {
	base, err := os.MkdirTemp("", "root-demo")
	if err != nil {
		panic(err)
	}
	defer os.RemoveAll(base)
	if err := os.Mkdir(filepath.Join(base, "reports"), 0o700); err != nil {
		panic(err)
	}
	if err := os.WriteFile(filepath.Join(base, "reports", "today.txt"), []byte("inside"), 0o600); err != nil {
		panic(err)
	}

	name := filepath.Join("reports", "today.txt")
	if !filepath.IsLocal(name) {
		panic("unexpected non-local path")
	}
	file, err := os.OpenInRoot(base, name)
	if err != nil {
		panic(err)
	}
	data, err := io.ReadAll(file)
	if err != nil {
		file.Close()
		panic(err)
	}
	if err := file.Close(); err != nil {
		panic(err)
	}
	fmt.Println(string(data))

	_, err = os.OpenInRoot(base, filepath.Join("..", "secret.txt"))
	fmt.Println("escape rejected:", err != nil)
}
